-- Spec 015: seat reservations and their holds (data-model.md; research R1, R2, R3, R6).
-- Generated by `prisma migrate dev --create-only`, then extended by hand with the CHECKs and
-- partial indexes Prisma's schema language can't express.

-- CreateEnum: why a hold ended. EXPIRED, RELEASED and LOGOUT start the 2-minute wait (FR-004a).
CREATE TYPE "SeatHoldEnd" AS ENUM ('EXPIRED', 'RELEASED', 'LOGOUT', 'BOUGHT', 'CLOSED');

-- CreateTable: one customer's 5-minute claim on seats of one event.
CREATE TABLE "SeatReservation" (
    "id" UUID NOT NULL,
    "eventId" UUID NOT NULL,
    "customerSub" TEXT NOT NULL,
    "tierId" UUID,
    "createdAt" TIMESTAMPTZ(6) NOT NULL,
    "expiresAt" TIMESTAMPTZ(6) NOT NULL,
    "endedAt" TIMESTAMPTZ(6),

    CONSTRAINT "SeatReservation_pkey" PRIMARY KEY ("id")
);

-- CreateTable: one seat in a reservation, kept after it ends.
CREATE TABLE "SeatHold" (
    "id" UUID NOT NULL,
    "reservationId" UUID NOT NULL,
    "eventId" UUID NOT NULL,
    "seatSection" TEXT NOT NULL,
    "seatRow" INTEGER NOT NULL,
    "seatNumber" INTEGER NOT NULL,
    "createdAt" TIMESTAMPTZ(6) NOT NULL,
    "releasedAt" TIMESTAMPTZ(6),
    "endReason" "SeatHoldEnd",

    CONSTRAINT "SeatHold_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "SeatReservation_customerSub_idx" ON "SeatReservation"("customerSub");
CREATE INDEX "SeatHold_reservationId_idx" ON "SeatHold"("reservationId");
-- Research R6: the 2-minute wait looks up recently ended holds.
CREATE INDEX "SeatHold_eventId_releasedAt_idx" ON "SeatHold"("eventId", "releasedAt");

-- Review of #38: the target of SeatHold's composite foreign key, so a hold's eventId always
-- equals its reservation's.
ALTER TABLE "SeatReservation" ADD CONSTRAINT "seat_reservation_id_event"
    UNIQUE ("id", "eventId");

-- AddForeignKey: reservations and holds go with their event, and reservations with their tier
-- (research R11). Neither can have orders, so nothing sold is lost.
ALTER TABLE "SeatReservation" ADD CONSTRAINT "SeatReservation_eventId_fkey"
    FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SeatReservation" ADD CONSTRAINT "SeatReservation_tierId_fkey"
    FOREIGN KEY ("tierId") REFERENCES "TicketTier"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SeatHold" ADD CONSTRAINT "SeatHold_eventId_fkey"
    FOREIGN KEY ("eventId") REFERENCES "Event"("id") ON DELETE CASCADE ON UPDATE CASCADE;
-- A hold's event is its reservation's event.
ALTER TABLE "SeatHold" ADD CONSTRAINT "seat_hold_reservation_event"
    FOREIGN KEY ("reservationId", "eventId") REFERENCES "SeatReservation"("id", "eventId")
    ON DELETE CASCADE ON UPDATE CASCADE;

-- FR-004 (research R3): exactly 5 minutes, never extended.
ALTER TABLE "SeatReservation" ADD CONSTRAINT "seat_reservation_five_minutes"
    CHECK ("expiresAt" = "createdAt" + interval '5 minutes');
ALTER TABLE "SeatReservation" ADD CONSTRAINT "seat_reservation_ended_after_start"
    CHECK ("endedAt" IS NULL OR "endedAt" >= "createdAt");

-- FR-003: at most one active reservation per customer per event.
CREATE UNIQUE INDEX "seat_reservation_one_active"
    ON "SeatReservation"("eventId", "customerSub") WHERE "endedAt" IS NULL;
-- Research R4: the sweep finds run-out reservations by their end.
CREATE INDEX "seat_reservation_open_by_expiry"
    ON "SeatReservation"("expiresAt") WHERE "endedAt" IS NULL;

ALTER TABLE "SeatHold" ADD CONSTRAINT "seat_hold_seat_positive"
    CHECK ("seatRow" >= 1 AND "seatNumber" >= 1);
ALTER TABLE "SeatHold" ADD CONSTRAINT "seat_hold_end_all_or_none"
    CHECK (("releasedAt" IS NULL) = ("endReason" IS NULL));

-- FR-009 (Constitution IV): no seat has two live holds for an event, whatever any client does.
-- Ended holds aren't indexed, so they never block anyone.
CREATE UNIQUE INDEX "seat_hold_one_live_per_seat"
    ON "SeatHold"("eventId", "seatSection", "seatRow", "seatNumber") WHERE "releasedAt" IS NULL;
